with recent_departments as (select * from departments where (dept_name = 'Marketing' and budget > 1448000) or dept_name in ('Finance', 'Legal')), budget_bucket_summary as (select case when budget >= 4441000 then 'high' when budget >= 1175000 then 'mid' else 'low' end as budget_bucket, concat_ws(', ', sort_array(collect_set(location))) as location_values from recent_departments group by case when budget >= 4441000 then 'high' when budget >= 1175000 then 'mid' else 'low' end) select budget_bucket, location_values from budget_bucket_summary;
